    <style>
        :root {
            --primary-navy: #0f172a;
            --primary-gold: #d4a017; /* Adjusted to match the warm gold in image */
            --text-dark: #1e293b;
            --text-light: #64748b;
            --bg-light: #ffffff;
            --bg-cream: #fdfbf7;
            --font-serif: "Georgia", "Times New Roman", serif;
