            font-size: 36px;
            color: var(--primary-gold);
            font-weight: bold;
            line-height: 1;
        }

        .logo-text h1 {
            font-size: 18px;
            color: var(--text-dark);
            font-weight: 700;
            line-height: 1.1;
        }

        .logo-text span {
            font-size: 10px;
            text-transform: uppercase;
            letter-spacing: 1px;
            color: var(--text-light);
            display: block;
        }

        .auth-buttons {
            display: flex;
            gap: 12px;
        }

        .btn-outline {
            border: 1px solid #cbd5e1;
            background: transparent;
            color: var(--text-dark);
            padding: 8px 20px;
            border-radius: 50px;
            text-decoration: none;
            font-weight: 600;
            font-size: 13px;
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .btn-filled {
            background-color: var(--primary-gold);
            color: white;
            border: none;
            padding: 8px 20px;
            border-radius: 50px;
            text-decoration: none;
            font-weight: 600;
            font-size: 13px;
            display: flex;
            align-items: center;
            gap: 6px;
        }

