            gap: 12px;
            margin-bottom: 16px;
            font-weight: 500;
            color: var(--text-dark);
        }

        .check-icon {
            color: var(--primary-gold);
            font-weight: bold;
            font-size: 18px;
        }

        /* Section 3: Hero / Trusted (White) */
        .section-hero {
            padding: 80px 0;
            background-color: white;
        }

        .hero-grid {
