            position: relative;
        }

        .hero-image-wrapper img {
            width: 100%;
            height: auto;
            display: block;
            aspect-ratio: 4/3;
            object-fit: cover;
        }

        .hero-content {
            flex: 0.9;
        }

        .hero-content h2 {
            font-family: var(--font-serif);
            font-size: 46px;
            color: var(--text-dark);
            margin-bottom: 24px;
            line-height: 1.1;
        }

        .hero-content > p {
            color: var(--text-light);
            font-size: 16px;
            line-height: 1.7;
            margin-bottom: 40px;
            max-width: 520px;
        }

        .stats-row {
            display: flex;
            gap: 20px;
            margin-bottom: 40px;
        }

        .stat-card {
            border: 1px solid #e2e8f0;
            border-radius: 16px;
            padding: 20px 24px;
            min-width: 140px;
            background: white;
        }

        .stat-card strong {
            display: block;
            font-size: 22px;
            color: var(--text-dark);
            margin-bottom: 4px;
            font-family: var(--font-sans);
        }

        .stat-card span {
            font-size: 12px;
            color: var(--text-light);
            line-height: 1.3;
            display: block;
        }

        /* Footer Strip */
        footer {
            background-color: var(--primary-navy);
            color: white;
            padding: 40px 0;
            font-size: 13px;
        }

        .footer-content {
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .footer-logo {
             font-family: var(--font-serif);
             font-size: 24px;
             color: var(--primary-gold);
        }

        .footer-links {
            display: flex;
            gap: 40px;
            color: var(--primary-gold);
            font-weight: bold;
            text-transform: uppercase;
            letter-spacing: 1px;
            font-size: 11px;
        }

        @media (max-width: 900px) {
            .testimonials-grid { grid-template-columns: 1fr; }
            .alterations-content { flex-direction: column; }
            .alterations-text { padding: 40px 20px; }
            .hero-grid { flex-direction: column; }
            .stats-row { flex-wrap: wrap; }
            header { padding: 16px 20px; }
        }
    </style>
</head>
